INSERT INTO `recipe_steps` (`id`, `recipeId`, `stepNumber`, `instruction`, `imagePath`, `durationMinutes`, `deletedAt`) VALUES
(1, 'ffb34583-b054-11f1-8f91-4a1fa1f06f0c', 1, 'Chần xương bò với nước sôi 5 phút, rửa sạch rồi cho vào nồi với 3 lít nước lạnh. Thêm gừng và hành tây nướng sơ vào ninh.', NULL, 5, NULL),
(2, 'ffb34583-b054-11f1-8f91-4a1fa1f06f0c', 2, 'Ninh xương bò ở lửa nhỏ trong 2-3 giờ. Vớt bọt thường xuyên để nước dùng trong. Nêm nước mắm, muối, đường cho vừa.', NULL, 180, NULL),
(3, 'ffb34583-b054-11f1-8f91-4a1fa1f06f0c', 3, 'Thái thịt bò bắp mỏng. Trần bánh phở qua nước sôi, cho vào tô. Xếp thịt bò lên trên.', NULL, 10, NULL),
(4, 'ffb34583-b054-11f1-8f91-4a1fa1f06f0c', 4, 'Chan nước dùng sôi vào tô. Garnish với hành lá, ngò rí, giá đỗ, chanh, ớt tươi.', NULL, 5, NULL),
(5, 'ffb4b01b-b054-11f1-8f91-4a1fa1f06f0c', 1, 'Đập trứng vào tô, thêm chút muối và tiêu, đánh tan đều.', NULL, 3, NULL),
(6, 'ffb4b01b-b054-11f1-8f91-4a1fa1f06f0c', 2, 'Phi thơm hành lá với dầu ăn ở lửa vừa. Đổ trứng vào chiên đến khi chín vàng hai mặt.', NULL, 7, NULL),
(7, 'ffb4b01b-b054-11f1-8f91-4a1fa1f06f0c', 3, 'Rạch bánh mì, kẹp trứng vào. Thêm tương ớt, dưa chuột thái lát tùy thích.', NULL, 5, NULL),
(8, 'ffb4b33d-b054-11f1-8f91-4a1fa1f06f0c', 1, 'Chần xương heo và bắp bò với nước sôi 5 phút rồi rửa sạch. Ninh với 3 lít nước ở lửa nhỏ 2 giờ.', NULL, 125, NULL),
(9, 'ffb4b33d-b054-11f1-8f91-4a1fa1f06f0c', 2, 'Phi sả, ớt, tỏi với dầu ăn rồi cho vào nồi nước dùng. Nêm mắm ruốc, muối, đường cho vừa.', NULL, 15, NULL),
(10, 'ffb4b33d-b054-11f1-8f91-4a1fa1f06f0c', 3, 'Trần bún qua nước sôi, cho vào tô. Xếp thịt bò, giò heo lên trên. Chan nước dùng sôi, thêm hành lá, ớt.', NULL, 10, NULL),
(11, 'ffb4b2ea-b054-11f1-8f91-4a1fa1f06f0c', 1, 'Vo gạo sạch, nấu với nước dùng xương heo tỉ lệ 1:8 ở lửa vừa đến khi gạo nở mềm.', NULL, 40, NULL),
(12, 'ffb4b2ea-b054-11f1-8f91-4a1fa1f06f0c', 2, 'Luộc lòng heo chín, thái mỏng. Xào sơ với tỏi phi, nêm nước mắm, tiêu.', NULL, 20, NULL),
(13, 'ffb4b2ea-b054-11f1-8f91-4a1fa1f06f0c', 3, 'Múc cháo ra tô, xếp lòng lên trên. Thêm hành lá, tiêu, gừng thái sợi.', NULL, 5, NULL),
(14, 'ffb4b272-b054-11f1-8f91-4a1fa1f06f0c', 1, 'Ngâm gạo nếp 4-6 tiếng. Đậu xanh ngâm 2 tiếng, hấp chín mềm rồi giã nhuyễn.', NULL, 10, NULL),
(15, 'ffb4b272-b054-11f1-8f91-4a1fa1f06f0c', 2, 'Trộn gạo nếp với chút muối và dầu ăn. Hấp cách thủy 30 phút đến khi xôi chín dẻo.', NULL, 35, NULL),
(16, 'ffb4b272-b054-11f1-8f91-4a1fa1f06f0c', 3, 'Phi hành khô vàng giòn. Múc xôi ra đĩa, rải đậu xanh và hành phi lên trên.', NULL, 10, NULL),
(17, 'ffb76f74-b054-11f1-8f91-4a1fa1f06f0c', 1, 'Chiên đậu phụ vàng đều hai mặt với dầu ăn ở lửa vừa.', NULL, 10, NULL),
(18, 'ffb76f74-b054-11f1-8f91-4a1fa1f06f0c', 2, 'Pha mắm tôm với chanh, đường, ớt, tỏi, dầu ăn phi thơm.', NULL, 5, NULL),
(19, 'ffb76f74-b054-11f1-8f91-4a1fa1f06f0c', 3, 'Bày bún, đậu phụ chiên, rau sống ra đĩa. Dùng kèm mắm tôm đã pha.', NULL, 5, NULL),
(20, 'ffb76ea2-b054-11f1-8f91-4a1fa1f06f0c', 1, 'Ướp thịt ba chỉ với sả, tỏi, nước mắm, đường, dầu hào 30 phút.', NULL, 30, NULL),
(21, 'ffb76ea2-b054-11f1-8f91-4a1fa1f06f0c', 2, 'Nướng thịt trên bếp than hoặc lò nướng 200°C đến khi vàng thơm, lật đều hai mặt.', NULL, 20, NULL),
(22, 'ffb76ea2-b054-11f1-8f91-4a1fa1f06f0c', 3, 'Pha nước mắm chua ngọt. Bày bún, thịt nướng, rau sống, đồ chua ra tô. Chan nước mắm.', NULL, 10, NULL),
(23, 'ffb76f20-b054-11f1-8f91-4a1fa1f06f0c', 1, 'Phi thơm tỏi với dầu ăn. Cho thịt bò thái hạt lựu vào xào chín săn.', NULL, 10, NULL),
(24, 'ffb76f20-b054-11f1-8f91-4a1fa1f06f0c', 2, 'Cho dưa cải, cà chua vào xào cùng. Nêm nước mắm, muối, đường.', NULL, 5, NULL),
(25, 'ffb76f20-b054-11f1-8f91-4a1fa1f06f0c', 3, 'Cho cơm nguội vào đảo đều lửa lớn đến khi cơm tơi, thơm. Thêm hành lá, tiêu.', NULL, 8, NULL),
(26, 'ffb76aee-b054-11f1-8f91-4a1fa1f06f0c', 1, 'Ướp sườn heo với sả, tỏi, nước mắm, đường, dầu hào 1 tiếng. Nướng hoặc chiên vàng.', NULL, 70, NULL),
(27, 'ffb76aee-b054-11f1-8f91-4a1fa1f06f0c', 2, 'Nấu cơm tấm. Làm chả trứng hấp từ trứng, thịt bằm, nấm mèo.', NULL, 30, NULL),
(28, 'ffb76aee-b054-11f1-8f91-4a1fa1f06f0c', 3, 'Pha nước mắm chua ngọt. Bày cơm, sườn, bì, chả ra đĩa. Chan nước mắm, dưa leo, cà chua.', NULL, 10, NULL),
(29, 'ffb76fb9-b054-11f1-8f91-4a1fa1f06f0c', 1, 'Xào tôm và thịt heo với sả, ớt, hành tím, nêm nước mắm, nghệ bột.', NULL, 15, NULL),
(30, 'ffb76fb9-b054-11f1-8f91-4a1fa1f06f0c', 2, 'Cho nước dùng xương vào xâm xấp, đun sôi. Nêm vừa ăn.', NULL, 10, NULL),
(31, 'ffb76fb9-b054-11f1-8f91-4a1fa1f06f0c', 3, 'Trần mỳ quảng chín, cho vào tô. Xếp tôm, thịt lên trên, chan ít nước nhân. Thêm rau sống, đậu phộng, bánh đa vừng.', NULL, 10, NULL),
(32, 'ffb979b0-b054-11f1-8f91-4a1fa1f06f0c', 1, 'Ướp cá basa với nước mắm, đường, tiêu, tỏi, gừng 15 phút.', NULL, 15, NULL),
(33, 'ffb979b0-b054-11f1-8f91-4a1fa1f06f0c', 2, 'Cho đường vào nồi đất thắng caramel. Thêm cá vào kho ở lửa nhỏ với nước dừa.', NULL, 25, NULL),
(34, 'ffb979b0-b054-11f1-8f91-4a1fa1f06f0c', 3, 'Kho đến khi nước cạn sệt, cá thấm đều. Thêm ớt, hành lá trước khi tắt bếp.', NULL, 10, NULL),
(35, 'ffb97a84-b054-11f1-8f91-4a1fa1f06f0c', 1, 'Phi thơm tỏi với dầu ăn. Cho cà chua vào xào sơ. Thêm 1 lít nước đun sôi.', NULL, 10, NULL),
(36, 'ffb97a84-b054-11f1-8f91-4a1fa1f06f0c', 2, 'Cho cá vào nấu chín. Nêm nước mắm, đường, giấm cho vị chua ngọt.', NULL, 10, NULL),
(37, 'ffb97a84-b054-11f1-8f91-4a1fa1f06f0c', 3, 'Cho đậu bắp, giá đỗ, rau ngổ vào. Nêm lại cho vừa ăn, tắt bếp.', NULL, 5, NULL),
(38, 'ffb97acc-b054-11f1-8f91-4a1fa1f06f0c', 1, 'Chặt gà thành miếng vừa ăn. Ướp với muối hột, ớt, tỏi, sả băm, nước mắm, dầu ăn 30 phút.', NULL, 35, NULL),
(39, 'ffb97acc-b054-11f1-8f91-4a1fa1f06f0c', 2, 'Nướng gà ở lò 200°C hoặc bếp than, lật đều đến khi vàng đều và chín hoàn toàn.', NULL, 35, NULL),
(40, 'ffb97acc-b054-11f1-8f91-4a1fa1f06f0c', 3, 'Bày gà ra đĩa. Dùng kèm rau sống, muối tiêu chanh.', NULL, 5, NULL),
(41, 'ffb975d6-b054-11f1-8f91-4a1fa1f06f0c', 1, 'Nấu nước dùng từ xương heo với sả, lá chanh, ớt, cà chua. Nêm mắm, muối, đường, nước cốt chanh cho vị chua cay.', NULL, 30, NULL),
(42, 'ffb975d6-b054-11f1-8f91-4a1fa1f06f0c', 2, 'Sơ chế hải sản: tôm bỏ đầu, mực cắt khoanh, cá phi lê. Rửa sạch rau ăn kèm.', NULL, 15, NULL),
(43, 'ffb975d6-b054-11f1-8f91-4a1fa1f06f0c', 3, 'Đun sôi nước dùng, nhúng hải sản và rau vào ăn liền. Dùng kèm bún hoặc mỳ.', NULL, 10, NULL),
(44, 'ffb97a3a-b054-11f1-8f91-4a1fa1f06f0c', 1, 'Luộc trứng chín, bóc vỏ. Thịt ba chỉ cắt miếng vuông 4cm, chần qua nước sôi.', NULL, 15, NULL),
(45, 'ffb97a3a-b054-11f1-8f91-4a1fa1f06f0c', 2, 'Thắng đường thành caramel vàng. Cho thịt vào đảo đều. Thêm nước dừa, nước mắm, tiêu, tỏi.', NULL, 10, NULL),
(46, 'ffb97a3a-b054-11f1-8f91-4a1fa1f06f0c', 3, 'Cho trứng vào kho cùng ở lửa nhỏ 45 phút đến khi thịt mềm, nước sệt lại. Nêm lại cho vừa.', NULL, 45, NULL),
(47, '62d87ced-e5a9-4be9-91ca-4a01cf1f682f', 1, 'Nấu gạo tẻ thành cháo nhừ', NULL, 20, NULL),
(48, '62d87ced-e5a9-4be9-91ca-4a01cf1f682f', 2, 'Đập trứng vào khuấy đều, nêm gia vị vừa ăn', NULL, 5, NULL),
(49, '628a8986-ab67-406c-ae2a-5132863347fa', 1, 'Đun nóng dầu ăn, làm trứng ốp la', NULL, 7, NULL),
(50, '628a8986-ab67-406c-ae2a-5132863347fa', 2, 'Rót sữa tươi ra ly thưởng thức cùng', NULL, 3, NULL),
(51, 'cc5a5266-5e4b-449f-a7b6-824981733cb5', 1, 'Phi thơm hành tây, cho cơm vào rang săn', NULL, 10, NULL),
(52, 'cc5a5266-5e4b-449f-a7b6-824981733cb5', 2, 'Đập trứng vào đảo đều đến khi hạt cơm vàng óng', NULL, 5, NULL),
(53, 'cb312ae5-eb38-4fc1-8af4-7573afd7849a', 1, 'Luộc đùi gà lấy nước nấu cháo', NULL, 20, NULL),
(54, 'cb312ae5-eb38-4fc1-8af4-7573afd7849a', 2, 'Xé thịt gà cho vào cháo, nêm nếm vừa ăn', NULL, 10, NULL),
(55, '6e10f381-f72d-473a-be58-587d8011f2da', 1, 'Luộc chín trứng gà trong 10 phút', NULL, 10, NULL),
(56, '6e10f381-f72d-473a-be58-587d8011f2da', 2, 'Dọn kèm ly sữa tươi ấm', NULL, 5, NULL),
(57, '20d9f43f-065d-4110-b9e3-bd760a896f94', 1, 'Nấu cháo nhừ', NULL, 15, NULL),
(58, '20d9f43f-065d-4110-b9e3-bd760a896f94', 2, 'Thêm hành tây thái nhỏ và trứng vào khuấy đều', NULL, 5, NULL),
(59, '41c8699b-72d4-42b6-8ab7-9c1242f13406', 1, 'Xào chín thịt nạc vai băm nhỏ', NULL, 10, NULL),
(60, '41c8699b-72d4-42b6-8ab7-9c1242f13406', 2, 'Cho cơm vào đảo đều tay cho săn hạt cơm', NULL, 10, NULL);
